const grid=document.querySelector('#journal-grid'),search=document.querySelector('#journal-search'),period=document.querySelector('#journal-period'),dialog=document.querySelector('#article-dialog');let category='all';const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function element(tag,text,cls){const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e}
function openArticle(a){const box=document.querySelector('#article-content');box.replaceChildren(element('p',a.label,'eyebrow blue'),element('h2',a.title),element('p',a.body));if(a.image){const img=element('img');img.src=a.image;img.alt=a.title;box.append(img,element('small',a.credit))}if(a.video){const frame=element('iframe');frame.src='https://www.youtube-nocookie.com/embed/'+a.video;frame.title=a.title;frame.allowFullscreen=true;frame.allow='encrypted-media; picture-in-picture';box.append(frame);const fallback=element('a','Voir la vidéo sur YouTube ↗','text-link');fallback.href='https://www.youtube.com/watch?v='+a.video;fallback.target='_blank';fallback.rel='noopener';box.append(fallback)}const link=element('a','Consulter la publication source ↗','button red');link.href=a.url;link.target='_blank';link.rel='noopener';box.append(link);dialog.showModal()}
function render(){const q=norm(search.value),list=articles.filter(a=>(category==='all'||a.tags.includes(category))&&(period.value!=='recent')&&norm(a.title+' '+a.intro+' '+a.label).includes(q));grid.replaceChildren();document.querySelector('#journal-count').textContent=list.length+' publication'+(list.length!==1?'s':'');for(const a of list){const card=element('article',null,'journal-card');if(a.image){const img=element('img');img.src=a.image;img.alt=a.title;img.loading='lazy';card.append(img)}else{const visual=element('div','▶','video-visual');visual.setAttribute('aria-hidden','true');card.append(visual)}const body=element('div',null,'journal-card-body');body.append(element('p',a.label,'eyebrow blue'),element('h3',a.title),element('p',a.intro));const b=element('button',a.video?'Lire & regarder ↗':'Lire l’article ↗','read-article');b.addEventListener('click',()=>openArticle(a));body.append(b);card.append(body);grid.append(card)}if(!list.length){const empty=element('div',null,'journal-empty');empty.append(element('h3',period.value==='recent'?'Les prochaines actualités arrivent ici.':'Aucune publication trouvée.'),element('p',period.value==='recent'?'Les contenus de la nouvelle saison seront publiés après validation par la ligue. Vous pouvez déjà explorer les événements passés.':'Modifiez la recherche ou choisissez une autre catégorie.'));grid.append(empty)}}
search.addEventListener('input',render);period.addEventListener('change',render);document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});render()}));function closeArticle(){dialog.close();document.querySelector('#article-content').replaceChildren()}document.querySelector('.dialog-close').addEventListener('click',closeArticle);dialog.addEventListener('close',()=>document.querySelector('#article-content').replaceChildren());dialog.addEventListener('click',e=>{if(e.target===dialog)closeArticle()});render();
